#include "platform/secret_envelope.hpp"
#include <stdexcept>
namespace squiflow::platform {
namespace {constexpr std::byte magic[]{std::byte{'S'},std::byte{'Q'},std::byte{'S'},std::byte{'1'}};void put32(std::vector<std::byte>& out,std::size_t at,std::uint32_t v){for(std::size_t i=0;i<4;++i)out[at+i]=static_cast<std::byte>((v>>(i*8U))&0xffU);}std::uint32_t get32(std::span<const std::byte> in,std::size_t at){std::uint32_t v=0;for(std::size_t i=0;i<4;++i)v|=static_cast<std::uint32_t>(in[at+i])<<(i*8U);return v;}}
std::vector<std::byte> encode_secret_envelope(std::span<const std::byte> value){if(value.empty()||value.size()>kMaxProtectedSecretLength)throw std::invalid_argument("protected secret size");std::vector<std::byte> out(kSecretEnvelopeHeaderSize+value.size());for(std::size_t i=0;i<4;++i)out[i]=magic[i];out[4]=std::byte{1};out[5]=out[6]=out[7]=std::byte{0};put32(out,8,static_cast<std::uint32_t>(value.size()));std::copy(value.begin(),value.end(),out.begin()+static_cast<std::ptrdiff_t>(kSecretEnvelopeHeaderSize));return out;}
SecretEnvelopeResult decode_secret_envelope(std::span<const std::byte> value)noexcept{if(value.size()<kSecretEnvelopeHeaderSize)return {};for(std::size_t i=0;i<4;++i)if(value[i]!=magic[i])return {};if(value[4]!=std::byte{1})return {false,SecretFault::UnsupportedVersion,{}};if(value[5]!=std::byte{0}||value[6]!=std::byte{0}||value[7]!=std::byte{0})return {};const std::uint32_t length=get32(value,8);if(length==0||length>kMaxProtectedSecretLength||value.size()!=kSecretEnvelopeHeaderSize+length)return {};return {true,SecretFault::None,value.subspan(kSecretEnvelopeHeaderSize,length)};}
}
